//! Windows `cmd.exe` + PowerShell + Sysinternals + AD command
//! compactors.
//!
//! Per-command files. Each one owns its detector + tests so a
//! Windows-only test failure doesn't pollute Linux/macOS test runs.
//!
//! `pub mod` declarations are auto-generated by `build.rs` from the
//! directory contents.
//!
//! Validated on the project's Windows VM via the compile scripts
//! under `install/windows/`. Fixtures captured from real `ipconfig`,
//! `tasklist`, `dir`, `netstat -ano`, `wmic`, `sc query` runs are
//! committed under `tests/fixtures/windows/` so unit tests don't
//! need a Windows host to re-run.
//!
//! Locale support: Windows output is heavily localised (the system
//! UI language wins). Detectors here key on locale-INVARIANT shapes
//! (column counts, structural separator dashes) wherever possible.

include!(concat!(env!("OUT_DIR"), "/cmd_windows_mods.rs"));

/// Content-shape dispatch — only includes shape-distinctive Windows
/// parsers. Most modules are passthrough/terse and reachable only
/// via name dispatch.
pub fn dispatch(text: &str) -> Option<String> {
    if let Some(out) = ipconfig::try_compact(text) {
        return Some(out);
    }
    if let Some(out) = tasklist::try_compact(text) {
        return Some(out);
    }
    if let Some(out) = netstat::try_compact(text) {
        return Some(out);
    }
    if let Some(out) = dir::try_compact(text) {
        return Some(out);
    }
    if let Some(out) = sc_query::try_compact(text) {
        return Some(out);
    }
    if let Some(out) = systeminfo::try_compact(text) {
        return Some(out);
    }
    if let Some(out) = wmic::try_compact(text) {
        return Some(out);
    }
    if let Some(out) = where_exe::try_compact(text) {
        return Some(out);
    }
    None
}
